import collections

class Node:
    def __init__(self, v):
        self.v = v
        self.l = None
        self.r = None

def insert(root, v):              # plain BST insert (invariant below)
    if root is None:
        return Node(v)
    if v < root.v:
        root.l = insert(root.l, v)
    else:
        root.r = insert(root.r, v)
    return root

# Build:      8
#           /   \
#          3    10
#         / \     \
#        1   6    14
#           / \   /
#          4   7 13
root = None
for v in [8, 3, 10, 1, 6, 14, 4, 7, 13]:
    root = insert(root, v)

def preorder(node, out):
    if node:
        out.append(node.v)          # node first
        preorder(node.l, out)
        preorder(node.r, out)

def inorder(node, out):
    if node:
        inorder(node.l, out)
        out.append(node.v)          # node between the subtrees
        inorder(node.r, out)

def postorder(node, out):
    if node:
        postorder(node.l, out)
        postorder(node.r, out)
        out.append(node.v)          # node last

pre, ino, post = [], [], []
preorder(root, pre); inorder(root, ino); postorder(root, post)
print(pre)    # [8, 3, 1, 6, 4, 7, 10, 14, 13]
print(ino)    # [1, 3, 4, 6, 7, 8, 10, 13, 14]  <- sorted!
print(post)   # [1, 4, 7, 6, 3, 13, 14, 10, 8]

q = collections.deque([root]); levels = []
while q:
    node = q.popleft()                     # level-order via queue
    levels.append(node.v)
    if node.l: q.append(node.l)
    if node.r: q.append(node.r)
print(levels) # [8, 3, 10, 1, 6, 14, 4, 7, 13]

class BST:
    def __init__(self):
        self.root = None

    def insert(self, v):                 # O(h)
        def rec(node):
            if node is None:
                return Node(v)
            if v < node.v:
                node.l = rec(node.l)
            else:                        # duplicates go right
                node.r = rec(node.r)
            return node
        self.root = rec(self.root)

    def search(self, v):                 # O(h)
        node = self.root
        while node and node.v != v:
            node = node.l if v < node.v else node.r
        return node is not None

